<script setup>import {ref} from 'vue';import {useRouter} from 'vue-router';import {login} from '../api/http';const router=useRouter(),username=ref('admin'),password=ref('admin123'),submitting=ref(false),errorMessage=ref('');async function submit(){errorMessage.value='';submitting.value=true;try{if(import.meta.env.VITE_DEMO_MODE==='true')localStorage.setItem('zhuatech_fms_token','demo-mode');else await login(username.value,password.value);await router.push('/admin/cockpit')}catch(e){errorMessage.value=e.response?.data?.message||'登录失败，请检查账号、密码和后端服务'}finally{submitting.value=false}}</script>
<template><div class="login-page"><section class="login-story"><div class="login-brand"><span>ZH</span><div><b>ZhuaTech FMS</b><small>知华科技财务管理系统</small></div></div><div class="story-copy"><p>FINANCE, CLEARLY MANAGED</p><h1>把每一笔资金，<br/>放回经营语境。</h1><span>连接账户、往来、预算与费用，让财务团队获得及时、可信、可追溯的经营信息。</span></div><div class="story-metric"><div><b>425.0 万</b><span>当前可用资金</span></div><div><b>86.4%</b><span>本月回款达成</span></div><div><b>58.1%</b><span>年度预算执行</span></div></div><footer>上海如静知华信息科技有限公司 · www.zhuatech.cn</footer></section><form @submit.prevent="submit"><p>安全登录</p><h2>进入财务运营中心</h2><label>账号<input v-model="username" autocomplete="username"/></label><label>密码<input v-model="password" type="password" autocomplete="current-password"/></label><div class="form-meta"><span>☑ 保持登录</span><a>无法登录？</a></div><p v-if="errorMessage" class="login-error">{{errorMessage}}</p><button class="button primary" :disabled="submitting">{{submitting?'正在验证…':'登录系统'}}</button><small>演示账号：admin / admin123</small></form></div></template>
